function option(id, label, feedback, strength = 'developing') { return { id, label, feedback, strength }; }
function check(prompt, correct, ...wrong) {
  return { prompt, options: [correct, ...wrong].map((label, index) => ({ id: String.fromCharCode(97 + index), label, isCorrect: index === 0 })) };
}

