export const rootSixLessons = lessons.map((lesson, index) => ({
  ...lesson,
  number: index + 1,
  displayNumber: String(index + 1).padStart(2, '0'),
  key: `harbor-${String(index + 1).padStart(2, '0')}-${lesson.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`,
  part: rootSixParts.find((part) => index + 1 >= part.range[0] && index + 1 <= part.range[1]),
  sources: lesson.sourceKeys.map((key) => sources[key]),
}));

export const rootSixQuickPrompts = ['Separate the facts from the fear', 'Show me what this tool does not protect', 'Help me prepare questions for a qualified professional'];

export function rootSixNarration(lesson) {
  return [lesson.sageOpen, ...lesson.story, ...lesson.understand, lesson.growth].join('\n\n');
}
